"use client";
import React from "react";
import { motion } from "framer-motion";
import { Info } from "lucide-react";
import { useBenchmarkData } from "@/hooks/useBenchmarkData";
import { formatUsd } from "@/lib/utils";

/**
 * Cost of the two error types, projected from one benchmark run.
 *
 * This replaces a six-month area chart whose series were generated by
 * multiplying a single measurement by a hardcoded `1 - month * 0.05` ramp. The
 * benchmark runs once and has no history, so plotting a trend implied
 * measurement that did not exist. What the data genuinely supports is a
 * comparison of two costs at a stated volume, with the assumptions on screen.
 *
 * Two bars, drawn in plain CSS rather than a chart library: the marks are
 * status-coloured (missed fraud = critical, false declines = warning), every
 * bar is directly labelled, and no legend is needed because each row names
 * itself.
 */

function CostBar({
  label,
  sublabel,
  value,
  max,
  barClass,
  textClass,
  delay,
}: {
  label: string;
  sublabel: string;
  value: number;
  max: number;
  barClass: string;
  textClass: string;
  delay: number;
}) {
  const pct = max > 0 ? Math.max(value > 0 ? 2 : 0, (value / max) * 100) : 0;

  return (
    <div>
      <div className="flex items-baseline justify-between gap-3 mb-1.5">
        <span className="text-[13px] font-medium text-ink">{label}</span>
        <span className={`text-[15px] font-semibold tabular-nums ${textClass}`}>
          {formatUsd(value)}
        </span>
      </div>
      <div className="h-2.5 rounded-full bg-surface-sunken overflow-hidden">
        <motion.div
          className={`h-full rounded-full ${barClass}`}
          initial={{ width: 0 }}
          animate={{ width: `${pct}%` }}
          transition={{ delay, duration: 0.7, ease: "easeOut" }}
        />
      </div>
      <p className="text-[11px] text-ink-3 mt-1.5 leading-snug">{sublabel}</p>
    </div>
  );
}

export default function FinancialImpactChart() {
  const { data } = useBenchmarkData();
  const model = data.costModel;
  const hasData = !data.isMock && model !== null;

  if (!hasData) {
    return (
      <section className="rounded-xl border border-line bg-surface shadow-card p-5">
        <h2 className="text-[15px] font-semibold text-ink">Modelled cost of errors</h2>
        <p className="text-[12px] text-ink-3 mt-0.5">
          Run a benchmark to project onboarding costs from measured error rates.
        </p>
        <div className="mt-8 mb-6 text-center text-[13px] text-ink-4">
          No benchmark results yet
        </div>
      </section>
    );
  }

  const max = Math.max(model.monthlyMissedFraudCost, model.monthlyFalseDeclineCost, 1);
  const totalCost = model.monthlyMissedFraudCost + model.monthlyFalseDeclineCost;

  return (
    <section className="rounded-xl border border-line bg-surface shadow-card p-5">
      <div className="mb-5">
        <h2 className="text-[15px] font-semibold text-ink">Modelled cost of errors</h2>
        <p className="text-[12px] text-ink-3 mt-0.5">
          Projected from this run&apos;s error rates at{" "}
          {model.monthlyMerchantVolume.toLocaleString()} merchants/month
        </p>
      </div>

      {/* Hero: value the system captures */}
      <div className="rounded-lg border border-risk-safe-border bg-risk-safe-soft px-4 py-3.5 mb-5">
        <div className="text-[11px] font-semibold uppercase tracking-[0.06em] text-risk-safe">
          Fraud prevented / month
        </div>
        <div className="text-[28px] font-semibold tabular-nums text-risk-safe leading-none mt-1.5">
          {formatUsd(model.monthlyFraudPrevented)}
        </div>
        <div className="text-[11px] text-ink-2 mt-1.5">
          Risky merchants blocked before onboarding
        </div>
      </div>

      <div className="space-y-5">
        <CostBar
          label="Missed fraud"
          sublabel={`False negatives — ${(model.falseNegativeRate * 100).toFixed(1)}% of risky merchants approved, at ${formatUsd(model.costPerFalseNegative)} each`}
          value={model.monthlyMissedFraudCost}
          max={max}
          barClass="bg-risk-danger"
          textClass="text-risk-danger"
          delay={0.1}
        />
        <CostBar
          label="False declines"
          sublabel={`False positives — ${(model.falsePositiveRate * 100).toFixed(1)}% of safe merchants blocked, at ${formatUsd(model.costPerFalsePositive)} each`}
          value={model.monthlyFalseDeclineCost}
          max={max}
          barClass="bg-risk-warn"
          textClass="text-risk-warn"
          delay={0.2}
        />
      </div>

      <div className="mt-5 pt-4 border-t border-line flex items-baseline justify-between">
        <span className="text-[13px] text-ink-2">Total monthly error cost</span>
        <span className="text-[16px] font-semibold text-ink tabular-nums">
          {formatUsd(totalCost)}
        </span>
      </div>

      {/* Assumptions stated on screen — this is a model, not a measurement */}
      <div className="mt-4 flex items-start gap-2 rounded-lg bg-surface-muted px-3 py-2.5">
        <Info className="w-3.5 h-3.5 text-ink-3 mt-0.5 flex-shrink-0" aria-hidden />
        <p className="text-[11px] text-ink-3 leading-relaxed">
          Projection, not a measurement. Assumes{" "}
          {model.monthlyMerchantVolume.toLocaleString()} merchants/month,{" "}
          {(model.highRiskPrevalence * 100).toFixed(0)}% high-risk prevalence,{" "}
          {formatUsd(model.costPerFalseNegative)} per missed fraud (chargebacks and scheme
          fines) and {formatUsd(model.costPerFalsePositive)} per false decline (lost
          merchant lifetime value).
        </p>
      </div>
    </section>
  );
}
